const languageNames = { en:'English', 'zh-Hant-HK':'繁體中文', 'zh-CN':'简体中文' };
function translationsFor(pathname){
  const group=translationGroups.find(paths=>paths.includes(pathname));
  if(!group)return [];
  return [
    {lang:'en',path:group[0]},
    {lang:'zh-Hant-HK',path:group[1]},
    {lang:'zh-CN',path:group[2]},
  ];
}
function languageLinks(page){return translationsFor(page.path).filter(item=>item.path!==page.path).map(item=>`<a class="button secondary" lang="${item.lang}" hreflang="${item.lang}" href="${item.path}">${languageNames[item.lang]}</a>`).join('');}

function esc(value=''){return String(value).replace(/[&<>\"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));}
function canonical(p){return `${origin}${p}`;}
function layout(page, body, type='Service'){
  const zh=page.lang.startsWith('zh'); const cn=page.lang==='zh-CN'; const home=cn?'/zh-cn/':(zh?'/?lang=zh':'/?lang=en');
  const primary={"@type":type,"@id":`${canonical(page.path)}#primary`,name:page.h1,description:page.description,url:canonical(page.path)};
  if(type==='Service'){primary.provider={"@id":`${origin}/#organization`};primary.areaServed=['Hong Kong','Greater China','Global'];}
  if(type==='Article'){primary.author={"@id":`${origin}/#organization`};primary.publisher={"@id":`${origin}/#organization`};primary.dateModified=updated;primary.headline=page.h1;}
  if(type==='CreativeWork'){primary.creator={"@id":`${origin}/#organization`};primary.dateModified=updated;}
  const graph=[{"@type":"Organization","@id":`${origin}/#organization`,name:'Onyx Devs Lab',url:`${origin}/`,email:'info@onyxdevslab.com',areaServed:['Hong Kong','Greater China','Global']},{"@type":"WebSite","@id":`${origin}/#website`,url:`${origin}/`,name:'Onyx Devs Lab',publisher:{"@id":`${origin}/#organization`},inLanguage:['en','zh-Hant-HK','zh-CN']},primary,{"@type":"WebPage","@id":canonical(page.path),url:canonical(page.path),name:page.title,description:page.description,dateModified:updated,inLanguage:page.lang,isPartOf:{"@id":`${origin}/#website`},about:{"@id":`${canonical(page.path)}#primary`}},{"@type":"BreadcrumbList",itemListElement:[{"@type":"ListItem",position:1,name:cn?'首页':(zh?'首頁':'Home'),item:`${origin}/`},{"@type":"ListItem",position:2,name:page.h1,item:canonical(page.path)}]}];
  if(page.faqs)graph.push({"@type":"FAQPage",mainEntity:page.faqs.map(([question,answer])=>({"@type":"Question",name:question,acceptedAnswer:{"@type":"Answer",text:answer}}))});
  if(page.people)graph.push(...page.people.map(person=>({"@type":"Person","@id":`${canonical(page.path)}#${person.name.toLowerCase()}`,name:person.name,jobTitle:person.role[cn?'cn':(zh?'zh':'en')],description:person.summary[cn?'cn':(zh?'zh':'en')],image:canonical(person.image),worksFor:{"@id":`${origin}/#organization`}})));
  const schema={"@context":"https://schema.org","@graph":graph};
  const alternates=translationsFor(page.path); const hreflangs=alternates.length?alternates.map(item=>`<link rel="alternate" hreflang="${item.lang}" href="${canonical(item.path)}">`).join('')+`<link rel="alternate" hreflang="x-default" href="${canonical(alternates[0].path)}">`:`<link rel="alternate" hreflang="${page.lang}" href="${canonical(page.path)}">`;
  const prefix=cn?'/zh-cn':(zh?'/zh-hk':'/en');
  return `<!doctype html><html lang="${page.lang}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(page.title)}</title><meta name="description" content="${esc(page.description)}"><link rel="canonical" href="${canonical(page.path)}">${hreflangs}<meta property="og:type" content="article"><meta property="og:site_name" content="Onyx Devs Lab"><meta property="og:title" content="${esc(page.title)}"><meta property="og:description" content="${esc(page.description)}"><meta property="og:url" content="${canonical(page.path)}"><link rel="stylesheet" href="/geo.css"><link rel="icon" href="/favicon.svg"><script type="application/ld+json">${JSON.stringify(schema)}</script></head><body><a class="skip" href="#content">${cn?'跳到主要内容':(zh?'跳至主要內容':'Skip to content')}</a><header class="nav"><div class="wrap"><a class="brand" href="${home}">ONYX DEVS LAB</a><nav class="navlinks" aria-label="${cn?'主要导航':(zh?'主要導航':'Primary')}"><a href="${prefix}/${zh?'ai-consulting':'ai-consulting-hong-kong'}/">${cn?'AI 咨询':(zh?'AI 顧問':'AI advisory')}</a><a href="${prefix}/${zh?'custom-ai-development':'custom-ai-development-hong-kong'}/">${cn?'定制开发':(zh?'定制開發':'Custom development')}</a><a href="${prefix}/forward-deployed-engineering/">FDE</a><a href="${prefix}/about/">${cn?'团队':(zh?'團隊':'Team')}</a><a href="mailto:info@onyxdevslab.com">${cn?'联系':(zh?'聯絡':'Contact')}</a></nav></div></header>${body}<footer class="footer"><div class="wrap">© 2026 Onyx Devs Lab · ${cn?'面向香港及跨境企业的 AI 咨询、定制开发与前线部署工程':(zh?'香港及跨境企業 AI 顧問、定制開發與前線部署工程':'AI advisory, custom development, and Forward Deployed Engineering for Hong Kong and cross-border enterprises')} · <a href="mailto:info@onyxdevslab.com">info@onyxdevslab.com</a></div></footer></body></html>`;
}
function relatedBody(p){const zh=p.lang.startsWith('zh');const cn=p.lang==='zh-CN';const prefix=cn?'/zh-cn':(zh?'/zh-hk':'/en');return `<section class="related"><div class="wrap"><h2>${cn?'相关交付证据':(zh?'相關交付證據':'Related delivery evidence')}</h2><a href="${prefix}/case-studies/retail-ai-decision-platform/">${cn?'零售 AI 决策平台案例':(zh?'零售 AI 決策平台案例':'Retail AI decision platform case study')}</a><a href="${prefix}/case-studies/accounting-ai-production-platform/">${cn?'AI 原生会计生产平台案例':(zh?'AI 原生會計生產平台案例':'AI-native accounting production platform case study')}</a>${zh?'':`<a href="/en/insights/what-is-forward-deployed-engineering/">What is Forward Deployed Engineering?</a>`}</div></section>`;}
function serviceBody(p){const zh=p.lang.startsWith('zh');const cn=p.lang==='zh-CN';const home=cn?'/zh-cn/':(zh?'/zh-hk/':'/en/');return `<main id="content"><div class="wrap breadcrumbs"><a href="${home}">${cn?'首页':(zh?'首頁':'Home')}</a> / ${esc(p.eyebrow)}</div><section class="hero"><div class="wrap"><div class="eyebrow">${esc(p.eyebrow)}</div><h1>${esc(p.h1)}</h1><p class="lede">${esc(p.lede)}</p><div class="actions"><a class="button" href="mailto:info@onyxdevslab.com?subject=${encodeURIComponent(p.h1)}">${cn?'预约项目评估':(zh?'預約項目評估':'Book a project assessment')}</a>${languageLinks(p)}</div></div></section><div class="wrap proof">${p.proof.map(x=>`<div><strong>${esc(x[0])}</strong><span>${esc(x[1])}</span></div>`).join('')}</div>${p.sections.map(s=>`<section><div class="wrap"><h2>${esc(s[0])}</h2><p class="intro">${esc(s[1])}</p><div class="grid">${s[2].map(c=>`<article class="card"><h3>${esc(c[0])}</h3><p>${esc(c[1])}</p></article>`).join('')}</div></div></section>`).join('')}<section><div class="wrap"><h2>${cn?'交付方法':(zh?'交付方法':'Delivery method')}</h2><div class="steps">${p.steps.map(s=>`<div class="step"><div><h3>${esc(s[0])}</h3><p class="intro">${esc(s[1])}</p></div></div>`).join('')}</div></div></section>${relatedBody(p)}<section class="faq"><div class="wrap"><h2>${cn?'常见问题':(zh?'常見問題':'Frequently asked questions')}</h2>${p.faqs.map(f=>`<details><summary>${esc(f[0])}</summary><p>${esc(f[1])}</p></details>`).join('')}<div class="cta"><h2>${cn?'从一个具体业务问题开始。':(zh?'從一個具體業務問題開始。':'Start with one concrete operating problem.')}</h2><p class="intro">${cn?'我们会先确认流程、证据、数据边界和结果标准，再建议下一步。':(zh?'我們會先確認流程、證據、數據邊界及成果標準，再建議下一步。':'We will first clarify the workflow, evidence, data boundary, and outcome standard before recommending the next step.')}</p><a class="button" href="mailto:info@onyxdevslab.com">${cn?'联系 Onyx':(zh?'聯絡 Onyx':'Contact Onyx')}</a></div></div></section></main>`;}
function caseBody(p){
  const zh=p.lang.startsWith('zh');
  const cn=p.lang==='zh-CN';
  const validationKey=p.path.includes('retail-')?'retail':'accounting';
  const metrics=caseValidation[validationKey][cn?'cn':(zh?'zh':'en')];
  const home=cn?'/zh-cn/':(zh?'/zh-hk/':'/en/');
  return `<main id="content"><div class="wrap breadcrumbs"><a href="${home}">${cn?'首页':(zh?'首頁':'Home')}</a> / ${cn?'案例':(zh?'案例':'Case studies')}</div><section class="hero"><div class="wrap"><div class="eyebrow">${cn?'案例 · 交付证据':(zh?'案例 · 交付證據':'Case study · Delivery evidence')}</div><h1>${esc(p.h1)}</h1><p class="lede">${esc(p.lede)}</p><div class="actions">${languageLinks(p)}</div></div></section><section><div class="wrap"><h2>${cn?'业务问题':(zh?'營運問題':'The operating challenge')}</h2><p class="intro">${esc(p.challenge)}</p></div></section><section><div class="wrap"><h2>${cn?'系统干预':(zh?'系統干預':'Designed intervention')}</h2><div class="grid">${p.work.map((x,i)=>`<article class="card"><div class="eyebrow">0${i+1}</div><p>${esc(x)}</p></article>`).join('')}</div></div></section><section><div class="wrap"><h2>${cn?'验证快照':(zh?'驗證快照':'Validation snapshot')}</h2><p class="intro">${cn?'以下数据同时展示已完成范围与试点验证结果；每项指标保留测量口径，避免把产品范围误解为业务结果。':(zh?'以下數據同時呈現已完成範圍與試點驗證結果；每項指標保留口徑，避免把產品範圍誤解為業務成果。':'These figures separate delivered scope from pilot validation. Each metric retains its measurement definition so product coverage is not mistaken for business impact.')}</p><div class="metric-grid">${metrics.map(([value,label,detail])=>`<article class="metric"><strong>${esc(value)}</strong><h3>${esc(label)}</h3><p>${esc(detail)}</p></article>`).join('')}</div></div></section><section><div class="wrap"><h2>${cn?'证据边界':(zh?'證據邊界':'Evidence boundary')}</h2><p class="intro">${esc(p.evidence)}</p><div class="cta"><h2>${cn?'讨论一个相近的业务问题。':(zh?'討論一個相近的營運問題。':'Discuss a comparable operating problem.')}</h2><a class="button" href="mailto:info@onyxdevslab.com?subject=Case%20study%20enquiry">${cn?'预约项目评估':(zh?'預約項目評估':'Book a project assessment')}</a></div></div></section></main>`;
}
function hubBody(p){const zh=p.lang.startsWith('zh');const cn=p.lang==='zh-CN';return `<main id="content"><section class="hero"><div class="wrap"><div class="eyebrow">${cn?'企业 AI 服务 · 香港':(zh?'企業 AI 服務 · 香港':'Enterprise AI services · Hong Kong')}</div><h1>${esc(p.h1)}</h1><p class="lede">${esc(p.lede)}</p><div class="actions">${languageLinks(p)}</div></div></section><section><div class="wrap"><h2>${cn?'选择合作方式':(zh?'選擇合作方式':'Choose the engagement model')}</h2><div class="grid">${p.links.map(([title,href,text])=>`<article class="card"><h3><a href="${href}">${esc(title)}</a></h3><p>${esc(text)}</p></article>`).join('')}</div><div class="cta"><h2>${cn?'从一个具体业务问题开始。':(zh?'從一個具體業務問題開始。':'Start with one concrete operating problem.')}</h2><a class="button" href="mailto:info@onyxdevslab.com">${cn?'预约项目评估':(zh?'預約項目評估':'Book a project assessment')}</a></div></div></section></main>`;}
function aboutBody(p){const zh=p.lang.startsWith('zh');const cn=p.lang==='zh-CN';const home=cn?'/zh-cn/':(zh?'/zh-hk/':'/en/');const key=cn?'cn':(zh?'zh':'en');return `<main id="content"><div class="wrap breadcrumbs"><a href="${home}">${cn?'首页':(zh?'首頁':'Home')}</a> / ${cn?'团队':(zh?'團隊':'Team')}</div><section class="hero"><div class="wrap"><div class="eyebrow">${cn?'关于 Onyx':(zh?'關於 Onyx':'About Onyx')}</div><h1>${esc(p.h1)}</h1><p class="lede">${esc(p.lede)}</p><div class="actions">${languageLinks(p)}</div></div></section><section><div class="wrap"><h2>${cn?'核心团队':(zh?'核心團隊':'Core team')}</h2><div class="people-grid">${p.people.map(person=>`<article class="person"><img src="${person.image}" alt="${esc(person.name)}" width="96" height="96"><div><h3>${esc(person.name)}</h3><div class="eyebrow">${esc(person.role[key])}</div><p>${esc(person.summary[key])}</p></div></article>`).join('')}</div><div class="cta"><h2>${cn?'直接和负责交付的人讨论。':(zh?'直接與負責交付的人討論。':'Talk directly with the people responsible for delivery.')}</h2><a class="button" href="mailto:info@onyxdevslab.com">${cn?'预约项目评估':(zh?'預約項目評估':'Book a project assessment')}</a></div></div></section></main>`;}

for(const p of pages){const out=path.join(dist,p.path,'index.html');fs.mkdirSync(path.dirname(out),{recursive:true});fs.writeFileSync(out,layout(p,serviceBody(p),p.schemaType||(p.path.includes('/insights/')?'Article':'Service')));}
for(const p of cases){const out=path.join(dist,p.path,'index.html');fs.mkdirSync(path.dirname(out),{recursive:true});fs.writeFileSync(out,layout(p,caseBody(p),'CreativeWork'));}
for(const p of hubs){const out=path.join(dist,p.path,'index.html');fs.mkdirSync(path.dirname(out),{recursive:true});fs.writeFileSync(out,layout(p,hubBody(p),'CollectionPage'));}
for(const p of aboutPages){const out=path.join(dist,p.path,'index.html');fs.mkdirSync(path.dirname(out),{recursive:true});fs.writeFileSync(out,layout(p,aboutBody(p),'AboutPage'));}

const all=['/',...hubs.map(p=>p.path),...aboutPages.map(p=>p.path),...pages.map(p=>p.path),...cases.map(p=>p.path)];
const sitemap=`<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9" xmlns:xhtml="http://www.w3.org/1999/xhtml">\n${all.map(p=>{const alternates=translationsFor(p).map(item=>`<xhtml:link rel="alternate" hreflang="${item.lang}" href="${canonical(item.path)}"/>`).join('');return `  <url><loc>${canonical(p)}</loc><lastmod>${updated}</lastmod>${alternates}</url>`}).join('\n')}\n</urlset>\n`;
fs.writeFileSync(path.join(dist,'sitemap.xml'),sitemap);
console.log(`Generated ${pages.length + cases.length + hubs.length + aboutPages.length} GEO pages and sitemap.xml`);
